def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row if v not in (0, 1)}
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1

    # Copy the marker pattern to every placement where its marked cells
    # would all land on background zeros.
    additions = []
    for ar in range(h-sh+1):
        for ac in range(w-sw+1):
            if (ar, ac) == (r0, c0):
                continue
            cells = [(ar+dr, ac+dc) for dr, dc in shape]
            if all(g[r][c] == 0 for r, c in cells):
                additions.extend(cells)
    for r, c in additions:
        g[r][c] = color
    return g
